module width_8to16(
    input clk, 
    input rst_n, 
    input valid_in, 
    input [7:0] data_in,
    output reg valid_out, 
    output reg [15:0] data_out
);
// Register to hold the locked data during the first valid input
reg [7:0] data_lock;
// Flag to indicate whether we've received the first valid input
reg first_valid_received;
// Sequential logic to handle the output generation based on the clock and reset
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Resetting the data_out register to 0
        data_out <= 16'd0;

        // Resetting the first_valid_received flag
        first_valid_received <= 1'b0;

        // Resetting the valid_out signal
        valid_out <= 1'b0;
    end else begin
        // Checking if the input data is valid and if the first valid input has been received
        if (valid_in && first_valid_received) begin
            // Concatenating the locked data and the current data_in to generate data_out
            data_out <= {data_lock, data_in};

            // Setting the valid_out signal to indicate that the output is valid
            valid_out <= 1'b1;

            // Resetting the first_valid_received flag for the next pair of inputs
            first_valid_received <= 1'b0;
        end else if (valid_in && !first_valid_received) begin
            // Locking the current data_in into data_lock if it's the first valid input
            data_lock <= data_in;

            // Setting the first_valid_received flag to indicate that the first valid input has been received
            first_valid_received <= 1'b1;

            // Clearing the valid_out signal since we don't have the second input yet
            valid_out <= 1'b0;
        end else begin
            // Clearing the valid_out signal if neither condition is met
            valid_out <= 1'b0;
        end
    end
end
endmodule
